  "est_desc_home_cp": "మెయిన్ గేట్, పోర్చ్, గదులు మరియు బయటి పార్కింగ్ కోసం స్పష్టమైన నైట్ విజన్‌తో నమ్మకమైన భద్రత.",
  "est_desc_home_hik": "ముఖాలు, వాహన నంబర్ ప్లేట్లు స్పష్టంగా కనిపిస్తాయి; ఫోన్‌కు స్మార్ట్ మోషన్ అలర్ట్స్ వస్తాయి.",
