  "est_desc_office_cp": "రిసెప్షన్, క్యాబిన్లు, స్టాఫ్ డెస్క్, సర్వర్ రూమ్ మరియు ఎంట్రీ గేట్ పూర్తి నిఘా.",
  "est_desc_office_hik": "కమర్షియల్ క్లారిటీ, ఆడియో సపోర్ట్ మరియు ఒకేసారి అనేక ఫోన్లు/డెస్క్‌టాప్‌లలో లైవ్ వ్యూ.",
  "est_desc_office_prama": "ఆఫీస్ కారిడార్లు, యార్డులు, ఫ్యాక్టరీల కోసం హెవీ-డ్యూటీ 24/7 కలర్ నైట్ నిఘా.",
  "est_desc_shop_cp": "బిల్లింగ్ కౌంటర్, స్టాక్ రూమ్ మరియు షాప్ షట్టర్ ఎంట్రన్స్ కోసం పూర్తి నిఘా.",
  "est_desc_shop_hik": "కౌంటర్ వద్ద నోట్ల లెక్కింపు, కస్టమర్ స్పష్టత మరియు ఇన్‌బిల్ట్ మైక్ తో ఆడియో రికార్డింగ్.",
  "est_desc_shop_prama": "రాత్రి షట్టర్ వేసిన తర్వాత కూడా పగలు లాగా కలర్ ఫుటేజ్ — షాపులకు బలమైన భద్రత.",
