  "failed_check_availability": "సేవ లభ్యతను తనిఖీ చేయడంలో విఫలమైంది. దయచేసి నెట్‌వర్క్ చూడండి.",
  "faq_s_a1": "అవును. అన్ని TEAM CCTV Quote లలో 18% GST ముందే కలుపు ఉంటుంది — ఎలాంటి రహస్య ఛార్జీలు లేవు. Camera, DVR/NVR, కేబుల్, పూర్తి Fitting అన్నీ ఈ ధరలోనే ఉంటాయి.",
  "faq_s_a2": "అవును. ప్రతి Quote లో Camera బిగించడం, నీట్ గా వైరింగ్, DVR/NVR సెటప్, ఫోన్ App కనెక్షన్ మరియు పూర్తి డెమో అన్నీ ఉంటాయి.",
  "faq_s_a3": "పూర్తి 4-Camera సెటప్ బ్రాండ్ మరియు ఫీచర్లను బట్టి సుమారు ₹14,200 నుండి ₹18,000 వరకు ప్రారంభమవుతుంది. ఇందులో 18% GST, కేబుల్, Fitting అన్నీ ఉంటాయి.",
  "faq_s_a4": "అవును. CP Plus మరియు Prama మోడల్స్ కు BIS-ER సర్టిఫికేషన్ ఉంది — ఇల్లు, షాప్, సొసైటీ మరియు ప్రభుత్వ టెండర్లకు సరిపోతాయి. STQC ఆప్షన్ కూడా ఉంది.",
