  "tg_i3_bf": "బిల్లింగ్/క్యాష్ కౌంటర్, ఆఫీస్ రిసెప్షన్, ఎంట్రన్స్, హోమ్ లాబీ",
  "tg_i3_e": "కెమెరాలో ఉన్న మైక్ వీడియోతో పాటు మాట్లాడే మాటలు, చుట్టుపక్కల శబ్దాలను స్పష్టంగా రికార్డ్ చేస్తుంది.",
  "tg_i3_rl": "క్యాష్ కౌంటర్లు, రిసెప్షన్, ప్రధాన ద్వారం వద్ద జరిగే మాటలు, వాదనలకు ఖచ్చితమైన ఆధారంగా ఉంటుంది.",
  "tg_i3_t": "బిల్ట్-ఇన్ మైక్ & ఆడియో రికార్డింగ్",
  "tg_i4_b": "వైర్‌లెస్ & కొన్ని HD కెమెరాల్లో లభ్యం",
  "tg_i4_bf": "మెయిన్ గేట్, కారిడార్, అపార్ట్‌మెంట్ ప్రధాన ద్వారం",
  "tg_i4_e": "దీనిలో మైక్ మరియు స్పీకర్ రెండూ ఉంటాయి. మీరు మొబైల్ యాప్ నుండి లైవ్‌లో వినవచ్చు, మాట్లాడితే కెమెరా ద్వారా వినిపిస్తుంది.",
  "tg_i4_rl": "బయట ఉన్నప్పుడు డెలివరీ వారికి పార్శిల్ ఎక్కడ పెట్టాలో చెప్పవచ్చు, సిబ్బందితో మాట్లాడవచ్చు లేదా అనుమానాస్పద వ్యక్తులను హెచ్చరించవచ్చు.",
  "tg_i4_t": "2-వే మొబైల్ టాక్ (వాకీ-టాకీ)",
  "tg_i5_b": "స్మార్ట్ వైర్‌లెస్ మాత్రమే",
  "tg_i5_bf": "లివింగ్ రూమ్, పెద్ద దుకాణాలు, గోడౌన్లు, పెద్ద హాల్",
  "tg_i5_e": "మీ స్మార్ట్‌ఫోన్ యాప్ నుండి నేరుగా 360° అడ్డంగా మరియు 90° నిలువుగా తిప్పగలిగే మోటరైజ్డ్ కెమెరా.",
  "tg_i5_rl": "పెద్ద హాల్‌లో 2-3 కెమెరాలు పెట్టే బదులు, ఒకే తిరిగే కెమెరాతో ఎప్పుడైనా అన్ని వైపులా చూడవచ్చు.",
  "tg_i5_t": "360° తిరిగే కెమెరా (PTZ)",
  "tg_i6_b": "4G సిమ్ వైర్‌లెస్ మాత్రమే",
  "tg_i6_bf": "ఫామ్‌హౌస్‌లు, నిర్మాణ స్థలాలు, ప్లాట్లు, అవుట్‌పోస్ట్ గేట్లు",
  "tg_i6_e": "నేరుగా 4G సిమ్ (Jio / Airtel) తో పనిచేస్తుంది; ఎలాంటి బ్రాడ్‌బ్యాండ్ Wi-Fi లేదా కేబుల్స్ లేకుండానే మొబైల్ యాప్‌కు కనెక్ట్ అవుతుంది.",
  "tg_i6_rl": "బ్రాడ్‌బ్యాండ్ లేని ఫామ్‌హౌస్‌లు, నిర్మాణ స్థలాలు, గోడౌన్లు లేదా దూరపు గేట్లకు అత్యంత అనువైనది.",
  "tg_i6_t": "4G సిమ్ కార్డ్ కనెక్టివిటీ",
  "tg_real_life": "💡 నిజ జీవితంలో:",
  "tg_res_desc": "జూమ్ చేసినప్పుడు ముఖాలు, వాహన నంబర్ ప్లేట్లు ఎంత స్పష్టంగా కనిపిస్తాయో రిజల్యూషన్ నిర్ణయిస్తుంది. బయట మరియు లోపలి కెమెరాలకు వేరువేరుగా ఎంచుకోవచ్చు:",
  "tg_res_sub": "ప్రతి కెమెరా కార్డులోని RESOLUTION డ్రాప్‌డౌన్ ద్వారా మార్చవచ్చు",
